import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

async function auditPosts() {
  const posts = await prisma.posts.findMany({
    where: {
      status: 'published',
      post_type: 'post'
    },
    select: {
      slug: true,
      title: true,
      content: true,
      created_at: true,
      meta: true,
      featured_image: true
    },
    orderBy: { created_at: 'desc' }
  });

  // Filter to auto-generated posts (created 2025+ or has youtubeId)
  const autoGenerated = posts.filter(p => {
    const year = new Date(p.created_at).getFullYear();
    const hasYoutubeId = p.meta && p.meta.youtubeId;
    return year >= 2025 || hasYoutubeId;
  });

  console.log('='.repeat(80));
  console.log('AUDIT OF AUTO-GENERATED POSTS');
  console.log('='.repeat(80));
  console.log(`\nTotal auto-generated posts: ${autoGenerated.length}\n`);

  const issues = [];
  const good = [];

  for (const post of autoGenerated) {
    const content = post.content || '';
    const contentLength = content.length;
    const wordCount = content.replace(/<[^>]+>/g, ' ').split(/\s+/).filter(w => w.length > 0).length;

    // Check formatting
    const hasRacePhoto = content.includes('race-photo');
    const hasPhotoFloat = content.includes('photo-float');
    const imgCount = (content.match(/<img/gi) || []).length;
    const isWellFormatted = imgCount === 0 || (hasRacePhoto || hasPhotoFloat);

    // Check content quality
    const hasPullQuotes = content.includes('pull-quote');
    const hasStravaEmbed = content.includes('strava') || content.includes('Strava');
    const hasYoutubeEmbed = content.includes('youtube.com/embed') || content.includes('youtu.be');
    const paragraphCount = (content.match(/<p>/gi) || []).length;
    const h2Count = (content.match(/<h2/gi) || []).length;

    // Quality indicators
    const hasYoutubeId = post.meta && post.meta.youtubeId;
    const hasFeaturedImage = post.featured_image && post.featured_image.length > 0;

    // Determine if content is substantial (not just a stub)
    const isSubstantial = wordCount > 500;
    const hasStructure = h2Count >= 2 || paragraphCount >= 5;

    // Issues to flag
    const postIssues = [];

    if (wordCount < 300) {
      postIssues.push(`Very short (${wordCount} words)`);
    } else if (wordCount < 500) {
      postIssues.push(`Short (${wordCount} words)`);
    }

    if (imgCount > 0 && !isWellFormatted) {
      postIssues.push(`Images not styled (${imgCount} images)`);
    }

    if (!hasFeaturedImage) {
      postIssues.push('No featured image');
    }

    if (hasYoutubeId && !hasYoutubeEmbed) {
      postIssues.push('Has youtubeId but no embed');
    }

    if (!hasPullQuotes && wordCount > 500) {
      postIssues.push('No pull-quotes');
    }

    if (h2Count === 0 && wordCount > 300) {
      postIssues.push('No section headings');
    }

    if (postIssues.length > 0) {
      issues.push({
        slug: post.slug,
        title: post.title,
        wordCount,
        imgCount,
        issues: postIssues
      });
    } else {
      good.push({
        slug: post.slug,
        wordCount,
        imgCount
      });
    }
  }

  // Report issues
  console.log('='.repeat(80));
  console.log('POSTS WITH ISSUES');
  console.log('='.repeat(80));

  if (issues.length === 0) {
    console.log('\n✅ All posts look good!\n');
  } else {
    // Sort by number of issues (most issues first)
    issues.sort((a, b) => b.issues.length - a.issues.length);

    for (const post of issues) {
      console.log(`\n❌ ${post.slug}`);
      console.log(`   Words: ${post.wordCount}, Images: ${post.imgCount}`);
      post.issues.forEach(issue => {
        console.log(`   ⚠️  ${issue}`);
      });
    }

    console.log(`\n\nTotal with issues: ${issues.length}`);
  }

  // Summary of good posts
  console.log('\n' + '='.repeat(80));
  console.log('POSTS LOOKING GOOD');
  console.log('='.repeat(80));
  console.log(`\n✅ ${good.length} posts are well-formatted\n`);

  // Categorize issues
  const issueTypes = {};
  issues.forEach(p => {
    p.issues.forEach(issue => {
      const type = issue.split(' (')[0].split(' but')[0];
      issueTypes[type] = (issueTypes[type] || 0) + 1;
    });
  });

  console.log('Issue breakdown:');
  Object.entries(issueTypes).sort((a,b) => b[1] - a[1]).forEach(([type, count]) => {
    console.log(`  ${count}x ${type}`);
  });

  await prisma.$disconnect();
}

auditPosts();
